import{_ as o,o as t,c as n,a5 as i}from"./chunks/framework.DrDMl0tG.js";const p=JSON.parse('{"title":"Changelog: v2.16","description":"","frontmatter":{},"headers":[],"relativePath":"sections/changelog/v2.16.md","filePath":"sections/changelog/v2.16.md"}'),a={name:"sections/changelog/v2.16.md"};function r(s,e,d,c,l,m){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog-v2-16" tabindex="-1">Changelog: v2.16 <a class="header-anchor" href="#changelog-v2-16" aria-label="Permalink to &quot;Changelog: v2.16&quot;">​</a></h1><h2 id="v2-16-0-2026-11-15" tabindex="-1">v2.16.0 (2026-11-15) <a class="header-anchor" href="#v2-16-0-2026-11-15" aria-label="Permalink to &quot;v2.16.0 (2026-11-15)&quot;">​</a></h2><p><strong>RaiSim</strong></p><ul><li><strong>Runtime joints.</strong> <code>World::addRuntimeJoint()</code> connects two rigid objects or articulated links, also of different robots, with a <code>Fixed</code>, <code>Ball</code>, <code>Hinge</code> or <code>Slider</code> joint between simulation steps, and <code>World::removeRuntimeJoint()</code> removes it again. The joints keep the objects separate; their impulses are solved together with contacts, tendons and joint limits. The world XML (<code>&lt;runtime_joint&gt;</code>) saves them with their enabled and broken state, and checkpoints keep the state of the joints that exist; adding or removing a joint makes earlier checkpoints unrestorable. See <a href="./../RuntimeJoints.html">Runtime joints</a>. The new <code>runtime_joint_benchmark</code> times them.</li><li><code>World::discardPendingStep()</code> cancels a step prepared by <code>integrate1()</code> or <code>integrateNoContactDetection()</code> without solving, integrating or advancing the world time. It clears the prepared contacts and constraint rows and allows adding and removing objects, tendons and wires again; preparation already done (waking objects, advancing projectiles) is not rolled back.</li><li>Articulated systems use less memory and reuse their dynamics scratch storage between steps. <code>MatDyn</code> copies no longer allocate for empty matrices.</li><li>Windows: the native FEM mesher build compiles in RaiSim&#39;s message logger, and its external projects use explicit build directories.</li><li>The FEM mesher reads and tessellates more STEP files; six complex parts (a DC motor, a hollow section, a pneumatic cylinder, a servo horn, a socket screw and a sprocket) are checked against independent Open CASCADE measurements, and a knee mount is a browser regression case.</li><li>The <code>raisim_engine2</code> world editor (the <code>raisim_engine2/</code> tree and the <code>RAISIM_ENGINE2</code> CMake option) was removed from this repository.</li></ul><p><strong>raisimPy</strong></p><ul><li><code>raisimpy.RuntimeJoint</code> and <code>World.addRuntimeJoint()</code>, <code>getRuntimeJoint()</code>, <code>getRuntimeJoints()</code> and <code>removeRuntimeJoint()</code>; the <code>runtimeJoints.py</code> example.</li><li><code>World.discardPendingStep()</code>.</li></ul><p><strong>Examples and documentation</strong></p><ul><li>The C++ <code>runtime_joints</code> example.</li><li>The examples build with MSVC&#39;s <code>/bigobj</code>.</li><li>The Newton benchmark pages compare ten-step control intervals and random actuation, and normalize performance by hardware price.</li></ul>',8)])])}const g=o(a,[["render",r]]);export{p as __pageData,g as default};
